    func testMatchesReferenceEngine() {
        var compared = 0
        for c in cases {
            let clock = BreathClock(c.config)
            let profiles = RegionProfiles(
                clock: clock,
                exhalesThroughNose: c.exhalesThroughNose,
                bandha: false,
                hasFace: { phase in phase == .inhale ? c.faceInUsed : c.faceOutUsed })

            for frame in c.frames {
                let state = clock.at(frame.t)
                let got = PoseComposer.compose(
                    layers: c.pose,
                    breath: profiles.amounts(at: state),
                    options: PoseOptions(focus: c.focus,
                                         faces: FacePair(inhale: frame.faceIn, exhale: frame.faceOut)))

                for (id, tx, ty, sx, sy, px, py, opacity) in frame.layers {
                    guard let v = got[id] else {
                        XCTFail("\(c.exerciseID): no transform for \(id)")
                        continue
                    }
                    XCTAssertEqual(v.translate.x, tx, accuracy: tolerance, "\(c.exerciseID) \(id).translate.x at t=\(frame.t)")
                    XCTAssertEqual(v.translate.y, ty, accuracy: tolerance, "\(c.exerciseID) \(id).translate.y at t=\(frame.t)")
                    XCTAssertEqual(v.scale.x, sx, accuracy: tolerance, "\(c.exerciseID) \(id).scale.x at t=\(frame.t)")
                    XCTAssertEqual(v.scale.y, sy, accuracy: tolerance, "\(c.exerciseID) \(id).scale.y at t=\(frame.t)")
                    XCTAssertEqual(v.pivot.x, px, accuracy: tolerance, "\(c.exerciseID) \(id).pivot.x at t=\(frame.t)")
                    XCTAssertEqual(v.pivot.y, py, accuracy: tolerance, "\(c.exerciseID) \(id).pivot.y at t=\(frame.t)")
                    XCTAssertEqual(v.opacity, opacity, accuracy: tolerance, "\(c.exerciseID) \(id).opacity at t=\(frame.t)")
                    compared += 7
                }
            }
        }
        XCTAssertGreaterThan(compared, 0)
    }

    /// The head and ears cancel the root's breath stretch exactly. The face is a
    /// rigid lift: if the cancellation were approximate the character's features
    /// would breathe with its body, which is the single most obvious way for a
    /// rig like this to look wrong.
    func testCounterCancelsTheRootExactly() {
        for c in cases {
            let clock = BreathClock(c.config)
            let profiles = RegionProfiles(clock: clock, exhalesThroughNose: c.exhalesThroughNose)
            for frame in c.frames {
                let got = PoseComposer.compose(layers: c.pose,
                                               breath: profiles.amounts(at: clock.at(frame.t)))
                guard let root = got["root"], let head = got["head"] else { continue }
                XCTAssertEqual(root.scale.x * head.scale.x, 1, accuracy: 1e-15,
                               "\(c.exerciseID) head x at t=\(frame.t)")
                XCTAssertEqual(root.scale.y * head.scale.y, 1, accuracy: 1e-15,
                               "\(c.exerciseID) head y at t=\(frame.t)")
            }
        }
    }

    /// Seated trades arms for folded legs one-for-one, so the two stacks are the
    /// same length. Only the ids tell them apart — and a count that cannot has
    /// already hidden one failure in the reference.
    func testTheTwoBodiesDifferByIdNotByCount() {
        let standing = Set(PoseLayers.standing.map(\.id))
        let seated = Set(PoseLayers.seated.map(\.id))
        XCTAssertEqual(PoseLayers.standing.count, PoseLayers.seated.count)
        XCTAssertTrue(standing.contains("arms"))
        XCTAssertFalse(standing.contains("legs"))
        XCTAssertTrue(seated.contains("legs"))
        XCTAssertFalse(seated.contains("arms"))
    }
